function updateCategoryCoverageCard() {
    const coverageList = document.getElementById('categoryCoverageList');
    if (!coverageList) return;

    const officeFilterEl = document.getElementById('categoryCoverageOfficeFilter');
    const officeFilter = officeFilterEl ? officeFilterEl.value : 'ALL';
    const dataset = getFilteredOfficeData(officeFilter);
    const totalStaff = dataset.length;

    coverageList.innerHTML = '';
    trainingCategories.forEach(category => {
        const coveredCount = dataset.filter(staff =>
            staff.completedTrainings.some(training => training.category === category)
        ).length;

        const statusClass = coveredCount === 0 ? 'alert-critical' : (coveredCount < Math.ceil(totalStaff / 4) ? 'alert-warning' : 'alert-info');
        const statusText = coveredCount === 0 ? 'No staff covered' : `${coveredCount}/${totalStaff} staff covered`;

        const row = document.createElement('div');
        row.className = `alert-item ${statusClass}`;
        row.innerHTML = `<strong>${category}</strong>${statusText}`;
        coverageList.appendChild(row);
    });
}

function updateNeedsAttentionAlerts() {
    const container = document.getElementById('needsAttentionList');
    if (!container) return;

    const scope = iscmsOfficeHeadScope();
    const staffList = scope ? getFilteredOfficeData(scope) : getFilteredOfficeData('ALL');
    const officeKeys = scope ? [scope] : ['ACCA', 'ACES', 'ACLG', 'APC', 'CCES', 'ALTEC', 'SDU_ONLY'];
    const officeLabel = (key) => key === 'SDU_ONLY' ? 'SDU' : key;

    container.innerHTML = '';
    const competencyAlerts = [];
    const unequalAlerts = [];
    const overParticipationAlerts = [];
    const staffRoleGapAlerts = [];

    // 1) Competency gap by role per office
    const roleTypes = ['Participant', 'Facilitator', 'Organizer', 'Speaker', 'Host/Emcee', 'Documenter'];
    const roleToCountKey = { Participant: 'part', Facilitator: 'fac', Organizer: 'org', Speaker: 'spk', 'Host/Emcee': 'host', Documenter: 'doc' };
    const roleToTableLabel = { Participant: 'Participated', Facilitator: 'Facilitated', Organizer: 'Organized', Speaker: 'Speaker', 'Host/Emcee': 'Hosted/Emceed', Documenter: 'Documented' };
    officeKeys.forEach(officeKey => {
        const officeStaff = getFilteredOfficeData(officeKey);
        const roleCoverage = { Participant: 0, Facilitator: 0, Organizer: 0, Speaker: 0 };
        officeStaff.forEach(person => {
            person.completedTrainings.forEach(training => {
                roleCoverage[training.role] += 1;
            });
        });
        roleTypes.forEach(role => {
            if (roleCoverage[role] === 0) {
                competencyAlerts.push({
                    level: 'critical',
                    title: 'Competency Gap',
                    text: `No active ${role}s identified in ${officeLabel(officeKey)} based on recorded trainings.`
                });
            }
        });
    });

    // 2) Unequal distribution: staff with zero trainings per office
    officeKeys.forEach(officeKey => {
        const officeStaff = getFilteredOfficeData(officeKey);
        const zeroCount = officeStaff.filter(person => person.total === 0).length;
        if (zeroCount > 0) {
            unequalAlerts.push({
                level: 'warning',
                title: 'Unequal Distribution',
                text: `${zeroCount} staff in ${officeLabel(officeKey)} have 0 trainings recorded.`
            });
        }
    });

    // 3) Over-participation: top person vs overall average
    if (staffList.length > 0) {
        const totalTrainings = staffList.reduce((sum, person) => sum + person.total, 0);
        const average = totalTrainings / staffList.length;
        const topPerson = [...staffList].sort((a, b) => b.total - a.total)[0];
        if (topPerson && topPerson.total > average * 1.5) {
            overParticipationAlerts.push({
                level: 'info',
                title: 'Over-Participation',
                text: `${topPerson.name} is significantly above average training load (${topPerson.total} vs avg ${average.toFixed(1)}).`
            });
        }
    }

    // 4) Office head only: staff with trainings in the filtered window but 0 in a given role column
    if (scope) {
        const periodLabel = getGlobalFilterPeriodLabel();
        const officeStaff = getFilteredOfficeData(scope);
        officeStaff.forEach(person => {
            if (person.total === 0) return;
            roleTypes.forEach(role => {
                const key = roleToCountKey[role];
                if ((person[key] || 0) === 0) {
                    const col = roleToTableLabel[role];
                    staffRoleGapAlerts.push({
                        level: 'warning',
                        title: 'Staff role gap',
                        text: `${person.name} has 0 ${col} roles for ${periodLabel} (${officeLabel(scope)}).`
                    });
                }
            });
        });
    }

    const prioritizedAlerts = [];
    if (competencyAlerts.length) prioritizedAlerts.push(competencyAlerts[0]);
    if (unequalAlerts.length) prioritizedAlerts.push(unequalAlerts[0]);
    if (staffRoleGapAlerts.length) prioritizedAlerts.push(staffRoleGapAlerts[0]);
    if (overParticipationAlerts.length) prioritizedAlerts.push(overParticipationAlerts[0]);

    const remainingAlerts = [
        ...competencyAlerts.slice(1),
        ...unequalAlerts.slice(1),
        ...staffRoleGapAlerts.slice(1),
        ...overParticipationAlerts.slice(1)
    ];

    const maxAlerts = scope ? 14 : 6;
    const alerts = prioritizedAlerts.concat(remainingAlerts).slice(0, maxAlerts);

    if (alerts.length === 0) {
        const okRow = document.createElement('div');
        okRow.className = 'alert-item alert-info';
        okRow.innerHTML = '<strong>All Clear</strong>No critical competency or distribution flags detected from current data.';
        container.appendChild(okRow);
        return;
    }

    alerts.forEach(alert => {
        const row = document.createElement('div');
        row.className = `alert-item alert-${alert.level}`;
        row.innerHTML = `<strong>${alert.title}:</strong> ${alert.text}`;
        container.appendChild(row);
    });
}

// --- ISCMS Excel / spreadsheet export (HTML workbook with letterhead; opens in Excel) ---
const ISCMS_EXCEL_ASSETS = {
    logo: '../Img/Logo.png',
    seal: '../Img/Ateneo_de_Zamboanga_University_seal.png'
};

const ISCMS_EXCEL_HEADER = {
    university: 'Ateneo de Zamboanga University',
    location: 'La Purísima Street, Zamboanga City, Philippines',
    subtitle: 'Social Development Unit — ISCMS'
};

(function attachIscmsExcelExport(global) {
    function escapeCellHtml(value) {
        return String(value)
            .replace(/&/g, '&amp;')
            .replace(/</g, '&lt;')
            .replace(/>/g, '&gt;')
            .replace(/"/g, '&quot;');
    }

    function escapeDocText(value) {
        return String(value)
            .replace(/&/g, '&amp;')
            .replace(/</g, '&lt;')
            .replace(/>/g, '&gt;');
    }

    async function fetchImageDataUrl(relativePath) {
        try {
            const response = await fetch(relativePath);
            if (!response.ok) return '';
            const blob = await response.blob();
            return await new Promise((resolve, reject) => {
                const reader = new FileReader();
                reader.onload = () => resolve(reader.result);
                reader.onerror = reject;
                reader.readAsDataURL(blob);
            });
        } catch (e) {
            return '';
        }
    }

    function buildLetterheadTableHtml(logoSrc, sealSrc) {
        const leftImg = logoSrc
            ? `<img src="${logoSrc}" alt="" width="90" height="90" style="width:90px;height:90px;display:block;border:none;" />`
            : '';
        const rightImg = sealSrc
            ? `<img src="${sealSrc}" alt="" width="96" height="96" style="width:96px;height:96px;display:block;border:none;" />`
            : '';
        return `<table style="width:100%;border-collapse:collapse;margin-bottom:20px;font-family:Arial,sans-serif;">
<tr>
<td style="width:24%;vertical-align:middle;text-align:left;">${leftImg}</td>
<td style="width:52%;vertical-align:middle;text-align:center;padding:6px 10px;">
<div style="font-size:15pt;font-weight:bold;color:#1a237e;">${escapeDocText(ISCMS_EXCEL_HEADER.university)}</div>
<div style="font-size:10.5pt;margin-top:5px;color:#333;">${escapeDocText(ISCMS_EXCEL_HEADER.location)}</div>
<div style="font-size:10.5pt;margin-top:5px;font-weight:700;color:#333;">${escapeDocText(ISCMS_EXCEL_HEADER.subtitle)}</div>
</td>
<td style="width:24%;vertical-align:middle;text-align:right;">${rightImg}</td>
</tr>
</table>`;
    }

    function wrapExcelHtmlDocument(documentTitle, letterheadHtml, bodyInnerHtml) {
        return `<!DOCTYPE html>
<html xmlns:o="urn:schemas-microsoft-com:office:office" xmlns:x="urn:schemas-microsoft-com:office:excel">
<head>
<meta charset="utf-8">
<meta http-equiv="Content-Type" content="application/vnd.ms-excel; charset=utf-8">
<meta name="ExcelCreated" content="SDU-ISCMS">
<title>${escapeDocText(documentTitle)}</title>
<style>
body { font-family: Arial, sans-serif; }
table.iscms-data-grid { border-collapse: collapse; width: 100%; }
table.iscms-data-grid th, table.iscms-data-grid td { border: 1px solid #cccccc; padding: 6px 8px; font-size: 10pt; vertical-align: top; }
table.iscms-data-grid th { background: #f4f7fe; font-weight: 700; text-align: left; }
</style>
</head>
<body>
${letterheadHtml}
${bodyInnerHtml}
</body>
</html>`;
    }

    function tableFromMatrix(headerCells, dataRows) {
        const th = headerCells.map((c) => `<th>${escapeCellHtml(c)}</th>`).join('');
        const trs = dataRows
            .map((row) => `<tr>${row.map((c) => `<td>${escapeCellHtml(c)}</td>`).join('')}</tr>`)
            .join('');
        return `<table class="iscms-data-grid"><thead><tr>${th}</tr></thead><tbody>${trs}</tbody></table>`;
    }

    async function downloadExcelWithHeader(filenameBase, documentTitle, innerContentHtml) {
        const root = typeof global !== 'undefined' ? global : window;
        let logo =
            typeof root.ISCMS_EMBEDDED_LOGO_DATA_URL === 'string' && root.ISCMS_EMBEDDED_LOGO_DATA_URL.length > 500
                ? root.ISCMS_EMBEDDED_LOGO_DATA_URL
                : '';
        let seal =
            typeof root.ISCMS_EMBEDDED_SEAL_DATA_URL === 'string' && root.ISCMS_EMBEDDED_SEAL_DATA_URL.length > 500
                ? root.ISCMS_EMBEDDED_SEAL_DATA_URL
                : '';
        if (!logo) logo = await fetchImageDataUrl(ISCMS_EXCEL_ASSETS.logo);
        if (!seal) seal = await fetchImageDataUrl(ISCMS_EXCEL_ASSETS.seal);
        const letterhead = buildLetterheadTableHtml(logo, seal);
        const html = wrapExcelHtmlDocument(documentTitle, letterhead, innerContentHtml);
        const safeBase = String(filenameBase || 'export').replace(/\.(csv|xls|xlsx)$/i, '');
        const bom = '\ufeff';
        const blob = new Blob([bom + html], { type: 'application/vnd.ms-excel;charset=utf-8' });
        const url = URL.createObjectURL(blob);
        const link = document.createElement('a');
        link.href = url;
        link.download = `${safeBase}.xls`;
        link.style.display = 'none';
        document.body.appendChild(link);
        link.click();
        document.body.removeChild(link);
        URL.revokeObjectURL(url);
    }

    global.IscmsExcelExport = {
        downloadExcelWithHeader,
        tableFromMatrix,
        fetchImageDataUrl,
        ISCMS_EXCEL_ASSETS,
        ISCMS_EXCEL_HEADER
    };
})(typeof window !== 'undefined' ? window : globalThis);

// --- EXPORT TO EXCEL (spreadsheet with ISCMS letterhead) ---
async function exportToExcel(filename) {
    const domRows = document.querySelectorAll('#staffSection table tr');

    if (domRows.length <= 1) {
        alert('Please open an office directory first to export its data.');
        return;
    }

    const matrix = [];
    for (let i = 0; i < domRows.length; i++) {
        if (domRows[i].style.display === 'none') continue;
        const cols = domRows[i].querySelectorAll('td, th');
        matrix.push(Array.from(cols, (c) => c.innerText.trim()));
    }

    if (matrix.length <= 1) {
        alert('No visible rows to export.');
        return;
    }

    const headers = matrix[0];
    const dataRows = matrix.slice(1);
    const inner = IscmsExcelExport.tableFromMatrix(headers, dataRows);
    const baseName = (filename || 'staff_export').replace(/\.(csv|xls|xlsx)$/i, '');
    await IscmsExcelExport.downloadExcelWithHeader(baseName, 'SDU-ISCMS Staff Export', inner);
}

async function exportCategoryCoverageData() {
    const officeFilterEl = document.getElementById('categoryCoverageOfficeFilter');
    const officeFilter = officeFilterEl ? officeFilterEl.value : 'ALL';
    const dataset = getFilteredOfficeData(officeFilter);
    const totalStaff = dataset.length;

    if (totalStaff === 0) {
        alert('No category coverage data available for export.');
        return;
    }

    const headers = ['Category', 'Covered Staff', 'Total Staff', 'Coverage (%)', 'Status'];
    const dataRows = [];
    trainingCategories.forEach(category => {
        const coveredCount = dataset.filter(staff =>
            staff.completedTrainings.some(training => training.category === category)
        ).length;
        const pct = ((coveredCount / totalStaff) * 100).toFixed(1);
        const status = coveredCount === 0 ? 'No coverage' : (coveredCount < Math.ceil(totalStaff / 4) ? 'Low coverage' : 'Covered');
        dataRows.push([category, coveredCount, totalStaff, `${pct}%`, status]);
    });

    const inner = IscmsExcelExport.tableFromMatrix(headers, dataRows);
    await IscmsExcelExport.downloadExcelWithHeader(
        `Training_Category_Coverage_${officeFilter}`,
        'Training category coverage',
        inner
    );
}

async function exportTopPerformersData() {
    const officeF = document.getElementById('filterPerformersOffice').value;
    const categoryF = document.getElementById('filterPerformersCategory').value;
    const sortBy = document.getElementById('sortPerformersBy').value;

    let list = getFilteredOfficeData(officeF);
    if (categoryF !== 'ALL') {
        list = list.filter(person => person.completedTrainings.some(training => training.category === categoryF));
    }

    list.sort((a, b) => b[sortBy] - a[sortBy]);
    const topList = list.slice(0, 10);

    if (topList.length === 0) {
        alert('No top performer data available for export.');
        return;
    }

    const headers = ['Rank', 'Name', 'Office', 'Score', 'Sorted By', 'Category Filter'];
    const dataRows = topList.map((person, index) => [
        `#${index + 1}`,
        person.name,
        person.office,
        person[sortBy],
        sortBy,
        categoryF
    ]);

    const inner = IscmsExcelExport.tableFromMatrix(headers, dataRows);
    await IscmsExcelExport.downloadExcelWithHeader(
        `Top_Performers_${officeF}_${categoryF}_${sortBy}`,
        'Top performers',
        inner
    );
}

